const body = $input.first().json.body;
if (!body || body.event !== 'messages.upsert') return [];
const data = body.data;
if (!data || !data.key || data.key.fromMe === true) return [];
const phone = (data.key.remoteJid || '').split('@')[0].split(':')[0];
if (!phone || phone.length < 5) return [];
const msg = data.message || {};
const messageType = data.messageType || Object.keys(msg)[0] || '';
let route = 'skip', text = '', responseType = '';
if (messageType === 'audioMessage' || messageType === 'pttMessage') {
  route = 'audio';
} else if (messageType === 'buttonsResponseMessage') {
  responseType = ((msg.buttonsResponseMessage || {}).selectedButtonId || '').toLowerCase();
  if (!['confirm','edit','cancel'].includes(responseType)) responseType = 'unknown';
  route = 'response';
} else if (messageType === 'conversation' || messageType === 'extendedTextMessage') {
  text = msg.conversation || ((msg.extendedTextMessage || {}).text) || '';
  const t = text.trim().toLowerCase();
  if (t === '1' || t === 'potrdi') { route = 'response'; responseType = 'confirm'; }
  else if (t === '2' || t === 'popravi') { route = 'response'; responseType = 'edit'; }
  else if (t === '3' || t.startsWith('prekli')) { route = 'response'; responseType = 'cancel'; }
  else { route = 'text_new'; }
} else { return []; }
if (route === 'skip') return [];
return [{json: {phone, route, text, responseType, messageKey: data.key}}];

const {phone, messageKey} = $input.first().json;
const mData = await this.helpers.httpRequestWithAuthentication('httpHeaderAuth', {
  method: 'POST',
  url: 'http://evolution-api:8080/chat/getBase64FromMediaMessage/belpro',
  headers: {'Content-Type': 'application/json'},
  body: {key: messageKey},
  json: true
});
const b64 = (mData.base64 || '').replace(/^data:[^;]+;base64,/, '');
if (!b64) throw new Error('Ni zvočnega posnetka v sporočilu');
const audioBuf = Buffer.from(b64, 'base64');
const wResp = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://whisper:8001/transcribe',
  headers: {'Content-Type': 'audio/ogg'},
  body: audioBuf,
  returnFullResponse: true
});
const transcript = (typeof wResp.body === 'string' ? wResp.body : wResp.body.toString('utf-8')).trim();
const hoursM = transcript.match(/(\d+(?:[.,]\d+)?)\s*(?:uro|uri|ure|ur\b)/i);
const hours = hoursM ? parseFloat(hoursM[1].replace(',', '.')) : 1.0;
const today = new Date();
let entryDate = new Date(today);
const tl = transcript.toLowerCase();
if (tl.includes('včeraj') || tl.includes('vceraj')) {
  entryDate.setDate(today.getDate() - 1);
} else {
  const days = [{n:'ponedeljek',d:1},{n:'torku',d:2},{n:'torek',d:2},{n:'sredo',d:3},{n:'sredi',d:3},{n:'četrtek',d:4},{n:'cetrtek',d:4},{n:'petek',d:5},{n:'soboto',d:6},{n:'nedeljo',d:0}];
  for (const {n, d} of days) {
    if (tl.includes(n)) { const diff = ((today.getDay()-d)+7)%7||7; entryDate=new Date(today); entryDate.setDate(today.getDate()-diff); break; }
  }
  const dm = transcript.match(/\b(\d{1,2})[.\s]+(\d{1,2})\. /);
  if (dm) entryDate = new Date(today.getFullYear(), parseInt(dm[2])-1, parseInt(dm[1]));
}
const locM = transcript.match(/\b(?:v|pri|na)\s+([A-ZŠŽČĆĐ][a-zšžčćđ]+(?:\s+[A-ZŠŽČĆĐ][a-zšžčćđ]+)*)/);
const location = locM ? locM[1] : null;
let activity = transcript.replace(/(\d+(?:[.,]\d+)?)\s*(?:uro|uri|ure|ur\b)/gi,'').replace(/\b(danes|včeraj|vceraj|ponedeljek|torek|torku|sredo|sredi|četrtek|cetrtek|petek|soboto|nedeljo)\b/gi,'').replace(/\s{2,}/g,' ').trim()||transcript.trim();
return [{json: {phone, entry_date: entryDate.toISOString().split('T')[0], hours, activity_description: activity, location, raw_transcript: transcript}}];

const {phone, text} = $input.first().json;
const hoursM = text.match(/(\d+(?:[.,]\d+)?)\s*(?:uro|uri|ure|ur\b)/i);
const hours = hoursM ? parseFloat(hoursM[1].replace(',', '.')) : 1.0;
const today = new Date();
let entryDate = new Date(today);
const tl = text.toLowerCase();
if (tl.includes('včeraj') || tl.includes('vceraj')) {
  entryDate.setDate(today.getDate() - 1);
} else {
  const days = [{n:'ponedeljek',d:1},{n:'torku',d:2},{n:'torek',d:2},{n:'sredo',d:3},{n:'sredi',d:3},{n:'četrtek',d:4},{n:'cetrtek',d:4},{n:'petek',d:5},{n:'soboto',d:6},{n:'nedeljo',d:0}];
  for (const {n, d} of days) {
    if (tl.includes(n)) { const diff = ((today.getDay()-d)+7)%7||7; entryDate=new Date(today); entryDate.setDate(today.getDate()-diff); break; }
  }
  const dm = text.match(/\b(\d{1,2})[.\s]+(\d{1,2})\. /);
  if (dm) entryDate = new Date(today.getFullYear(), parseInt(dm[2])-1, parseInt(dm[1]));
}
const locM = text.match(/\b(?:v|pri|na)\s+([A-ZŠŽČĆĐ][a-zšžčćđ]+(?:\s+[A-ZŠŽČĆĐ][a-zšžčćđ]+)*)/);
const location = locM ? locM[1] : null;
let activity = text.replace(/(\d+(?:[.,]\d+)?)\s*(?:uro|uri|ure|ur\b)/gi,'').replace(/\b(danes|včeraj|vceraj|ponedeljek|torek|torku|sredo|sredi|četrtek|cetrtek|petek|soboto|nedeljo)\b/gi,'').replace(/\s{2,}/g,' ').trim()||text.trim();
return [{json: {phone, entry_date: entryDate.toISOString().split('T')[0], hours, activity_description: activity, location, raw_transcript: null}}];

const item = $input.first().json;
const {phone} = item;
const data = await this.helpers.httpRequestWithAuthentication('httpBasicAuth', {
  method: 'GET',
  url: `http://api:8000/api/volunteers?search_by=phone&search_q=${encodeURIComponent(phone)}&limit=1`,
  json: true
});
if (!data.total || data.total === 0) {
  return [{json: {...item, found: false}}];
}
const vol = data.items[0];
return [{json: {...item, found: true, volunteer_id: vol.id, volunteer_name: `${vol.first_name||''} ${vol.last_name||''}`.trim()}}];

const {phone} = $input.first().json;
await this.helpers.httpRequestWithAuthentication('httpHeaderAuth', {
  method: 'POST',
  url: 'http://evolution-api:8080/message/sendText/belpro',
  headers: {'Content-Type': 'application/json'},
  body: {number: phone, text: 'Vaša telefonska številka ni registrirana kot prostovoljec. Prosim kontaktirajte upravljalca.'},
  json: true
});
return [{json: {status: 'not_registered', phone}}];

const item = $input.first().json;
const entry = await this.helpers.httpRequestWithAuthentication('httpBasicAuth', {
  method: 'POST',
  url: 'http://api:8000/api/log-entries',
  headers: {'Content-Type': 'application/json'},
  body: {
    volunteer_id: item.volunteer_id,
    entry_date: item.entry_date,
    activity_description: item.activity_description,
    hours: parseFloat(item.hours) || 1.0,
    location: item.location || null,
    raw_transcript: item.raw_transcript || null,
    status: 'pending_volunteer'
  },
  json: true
});
if (!entry.id) throw new Error('Napaka pri ustvarjanju vnosa: ' + JSON.stringify(entry));
return [{json: {...item, entry_id: entry.id}}];

const item = $input.first().json;
const {phone, entry_id, entry_date, hours, activity_description, location, volunteer_name} = item;
const sd = $getWorkflowStaticData('global');
sd[phone] = {entry_id, entry_date, hours, activity_description, location, volunteer_name};
const d = new Date((entry_date||'2000-01-01')+'T12:00:00Z');
const dateStr = `${d.getUTCDate()}. ${d.getUTCMonth()+1}. ${d.getUTCFullYear()}`;
const msg = `Potrdite vnos:\n\n📅 Datum: ${dateStr}\n⏰ Ure: ${hours}\n📍 Kraj: ${location||'ni navedeno'}\n📝 Aktivnost: ${activity_description}\n\nOdgovorite:\n1 — ✅ Potrdi\n2 — ✏️ Popravi\n3 — ❌ Prekliči`;
await this.helpers.httpRequestWithAuthentication('httpHeaderAuth', {
  method: 'POST',
  url: 'http://evolution-api:8080/message/sendText/belpro',
  headers: {'Content-Type': 'application/json'},
  body: {number: phone, text: msg},
  json: true
});
return [{json: {phone, entry_id, status: 'awaiting_confirmation'}}];

const {phone, responseType} = $input.first().json;
const sd = $getWorkflowStaticData('global');
const state = sd[phone] || null;
if (!state) return [{json: {phone, responseType, entry_id: null}}];
return [{json: {phone, responseType, entry_id: state.entry_id, entry_date: state.entry_date, hours: state.hours, activity_description: state.activity_description, location: state.location, volunteer_name: state.volunteer_name}}];

const {phone} = $input.first().json;
await this.helpers.httpRequestWithAuthentication('httpHeaderAuth', {
  method: 'POST',
  url: 'http://evolution-api:8080/message/sendText/belpro',
  headers: {'Content-Type': 'application/json'},
  body: {number: phone, text: 'Ni aktivnega vnosa za potrditev. Pošljite glasovno sporočilo za nov vnos.'},
  json: true
});
return [{json: {status: 'no_pending_entry', phone}}];

const {phone, entry_id, entry_date, hours, activity_description, location, volunteer_name} = $input.first().json;
const EVO = 'http://evolution-api:8080';
const INST = 'belpro';
await this.helpers.httpRequestWithAuthentication('httpBasicAuth', {
  method: 'POST',
  url: `http://api:8000/api/log-entries/${entry_id}/confirm`,
  headers: {'Content-Type': 'application/json'},
  body: {},
  json: true
});
const sd = $getWorkflowStaticData('global');
delete sd[phone];
await this.helpers.httpRequestWithAuthentication('httpHeaderAuth', {
  method: 'POST',
  url: `${EVO}/message/sendText/${INST}`,
  headers: {'Content-Type': 'application/json'},
  body: {number: phone, text: 'Vnos je bil posredovan upravljalcu v odobritev. ✅'},
  json: true
});
const mgrsData = await this.helpers.httpRequestWithAuthentication('httpBasicAuth', {
  method: 'GET',
  url: 'http://api:8000/api/managers',
  json: true
});
const mgr = mgrsData.items ? mgrsData.items[0] : (Array.isArray(mgrsData) ? mgrsData[0] : mgrsData);
if (mgr && mgr.phone) {
  const d = new Date((entry_date||'2000-01-01')+'T12:00:00Z');
  const dateStr = `${d.getUTCDate()}. ${d.getUTCMonth()+1}. ${d.getUTCFullYear()}`;
  const mgrMsg = `Nov vnos čaka na odobritev:\n\n👤 ${volunteer_name||'Prostovoljec'}\n📅 ${dateStr} — ${hours} ur\n📝 ${activity_description||''}\n📍 ${location||'ni navedeno'}\n\nOdobritev: nadzorna plošča`;
  await this.helpers.httpRequestWithAuthentication('httpHeaderAuth', {
    method: 'POST',
    url: `${EVO}/message/sendText/${INST}`,
    headers: {'Content-Type': 'application/json'},
    body: {number: mgr.phone, text: mgrMsg},
    json: true
  });
}
return [{json: {phone, entry_id, status: 'confirmed'}}];

const {phone, entry_id} = $input.first().json;
await this.helpers.httpRequestWithAuthentication('httpBasicAuth', {
  method: 'DELETE',
  url: `http://api:8000/api/log-entries/${entry_id}`
});
const sd = $getWorkflowStaticData('global');
delete sd[phone];
await this.helpers.httpRequestWithAuthentication('httpHeaderAuth', {
  method: 'POST',
  url: 'http://evolution-api:8080/message/sendText/belpro',
  headers: {'Content-Type': 'application/json'},
  body: {number: phone, text: 'Vnos je bil zavržen. Pošljite glasovno sporočilo ali besedilo s popravkom.'},
  json: true
});
return [{json: {phone, entry_id, status: 'edit_requested'}}];

const {phone, entry_id} = $input.first().json;
await this.helpers.httpRequestWithAuthentication('httpBasicAuth', {
  method: 'DELETE',
  url: `http://api:8000/api/log-entries/${entry_id}`
});
const sd = $getWorkflowStaticData('global');
delete sd[phone];
await this.helpers.httpRequestWithAuthentication('httpHeaderAuth', {
  method: 'POST',
  url: 'http://evolution-api:8080/message/sendText/belpro',
  headers: {'Content-Type': 'application/json'},
  body: {number: phone, text: 'Vnos je bil preklican. ❌'},
  json: true
});
return [{json: {phone, entry_id, status: 'cancelled'}}];
